"use client"

import * as React from "react"
import { Checkbox as CheckboxPrimitive } from "@base-ui/react/checkbox"
import { Icon } from "@iconify/react"

import { cn } from "@/lib/utils"
import { useSound } from "./sound-provider"

// Clicky Checkbox — flat square with clean check state + tick sound

// Base UI className can be a state function; the wrapper feeds it to cn(), so
// narrow it to a plain string.
type WithClassName<P> = Omit<P, "className"> & { className?: string }

const Checkbox = React.forwardRef<
  HTMLButtonElement,
  WithClassName<CheckboxPrimitive.Root.Props>
>(({ className, onCheckedChange, ...props }, ref) => {
  const { playClick } = useSound()
  return (
    <CheckboxPrimitive.Root
      data-slot="checkbox"
      ref={ref}
      className={cn(
        "peer inline-flex items-center justify-center h-4 w-4 shrink-0 rounded-sm",
        "border border-border bg-background",
        "transition-all duration-base ease-out",
        "active:translate-y-px",
        "hover:border-ring/50",
        "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        "disabled:cursor-not-allowed disabled:opacity-50",
        "data-checked:bg-primary data-checked:border-[var(--primary-rim)] data-checked:text-primary-foreground",
        "data-checked:shadow-[var(--shadow-tactile-control)]",
        className
      )}
      onCheckedChange={(checked, eventDetails) => {
        playClick()
        onCheckedChange?.(checked, eventDetails)
      }}
      {...props}
    >
      <CheckboxPrimitive.Indicator data-slot="checkbox-indicator" className="size-full flex items-center justify-center text-current">
        <Icon icon="tabler:check" className="h-3.5 w-3.5" />
      </CheckboxPrimitive.Indicator>
    </CheckboxPrimitive.Root>
  )
})
Checkbox.displayName = "Checkbox"

export { Checkbox }
